    "abnormal_findings": [
      {
        "biomarker": "triglycerides",
        "value": 212.57,
        "unit": "mg/dL",
        "flag": "high",
        "comment": "Above the reference high of 150.0 mg/dL; may suggest hypertriglyceridaemia, needs clinical correlation with fasting status and diet."
      },
      {
        "biomarker": "ldl",
        "value": 150.81,
        "unit": "mg/dL",
        "flag": "high",
        "comment": "Above the reference high of 100.0 mg/dL; consistent with elevated LDL cholesterol, needs clinical correlation and cardiovascular risk assessment."
      },
      {
        "biomarker": "vitamin_d",
        "value": 15.22,
        "unit": "ng/mL",
        "flag": "low",
        "comment": "Below the reference low of 30.0 ng/mL; consistent with vitamin D insufficiency/deficiency, needs clinical correlation for supplementation decisions."
      }
    ],
    "lifestyle_restrictions": [
      "Respect Jain diet and peanut allergy in any diet plan.",
      "Diet plan request to be handled by the lifestyle coach; no medication changes without clinician approval."
    ],
    "recommended_followups": [
      "Cardiology review of elevated triglycerides (212.57 mg/dL) and LDL (150.81 mg/dL).",
      "General physician review of low vitamin D (15.22 ng/mL) and consideration of supplementation.",
      "Repeat lipid panel fasting to confirm values; confirm unit handling against the original report (source printed in mmol/L).",
      "Lifestyle/dietary counselling by the lifestyle coach for a Jain-compatible, peanut-free diet plan."
    ]
  }
}

response:
{
  "focus_areas": [
    "Lowering triglycerides (212.57 mg/dL) with a Jain, peanut-free diet low in refined carbs, sweets and deep-fried foods",
    "Reducing LDL cholesterol (150.81 mg/dL) with soluble fibre from dal, oats, barley and millets, and healthier cooking oils in measured amounts",
    "Correcting vitamin D deficiency (15.22 ng/mL) with safe sun exposure and vitamin D-rich foods, with supplementation decided only by your FOXO doctor",
    "Keeping every meal Jain-compatible (no onion, garlic, root vegetables, honey or eggs) and strictly peanut-free",
    "Gentle daily activity and a cardiology review for the lipid values, as advised by the doctor"
  ],
  "diet_recommendations": [
    {
      "item": "Breakfast (7:30-8:30 am): 1 bowl (about 150 g) lightly steamed moong sprouts or 1 bowl of moong dal cheela (2 small cheelas, pan-cooked with 1/2 tsp oil) with 1 tsp lemon and jeera. Rotate with 1 bowl (40 g dry) plain oats cooked in water or toned milk, 3-4 days a week.",
      "rationale": "Soluble fibre from whole legumes and oats binds cholesterol in the gut and helps bring LDL down; this is also a light, Jain-friendly start to the day with no onion, garlic or root vegetables.",
      "linked_biomarker": "ldl"
    },
    {
      "item": "Lunch (1-2 pm): 2 jowar or bajra rotis (or 1 bowl, about 150 g, cooked foxtail millet) + 1 bowl (150 g) dal (moong, masoor, chana or toor) + 1 bowl (150 g) Jain sabzi such as lauki, tinda, parwal, bhindi, karela or palak + 1 small bowl of curd. Use no more than 1 tsp of mustard or rice-bran oil for the whole meal.",
      "rationale": "Replacing white rice and maida rotis with whole millets and adding a generous dal and vegetable portion lowers the refined-carb load that drives triglycerides, while keeping the meal within a Jain kitchen.",
      "linked_biomarker": "triglycerides"
    },
    {
      "item": "Dinner (7:30-8:30 pm, at least 2-3 hours before sleeping): 1 bowl (150 g) cooked brown rice or 2 small jowar rotis + 1 bowl (150 g) rajma, chana or lobia (not peanut) + 1 bowl of cooked seasonal sabzi. Keep dinner the lightest meal of the day.",
      "rationale": "A lighter, earlier dinner with legumes instead of a heavy rice- or maida-based meal reduces the evening fat and carb load that raises triglycerides, and legume fibre supports LDL reduction.",
      "linked_biomarker": "triglycerides"
    },
    {
      "item": "Daily at breakfast: 1 tbsp (about 10 g) freshly ground flaxseed (alsi) and 1 tsp chia or sabja seeds soaked in warm water. Also use 1 tsp sesame (til) seeds in chutney or sprinkled on sabzi.",
      "rationale": "Flaxseed, chia and sesame provide plant omega-3 (ALA) and fibre, which are among the most useful diet changes for lowering triglycerides in a vegetarian kitchen.",
      "linked_biomarker": "triglycerides"
    },
    {
      "item": "Mid-morning snack (11 am): a small handful of almonds (about 20 g, roughly 15 almonds) and 2 walnuts. Check the packet label to confirm no peanut or peanut traces; avoid all readymade mixtures and chutneys.",
      "rationale": "Unsalted tree nuts in measured amounts improve the blood lipid profile and are a safe snack for you as long as they are strictly peanut-free.",
      "linked_biomarker": "ldl"
    },
    {
      "item": "Afternoon/evening snack (4-5 pm): 1 whole seasonal fruit (guava, apple, orange, papaya or pear) or 1 bowl of sprout chaat with lemon and jeera. Always eat the whole fruit, not juice.",
      "rationale": "Whole fruit gives fibre and slowly released sugar instead of the rapid sugar load of juices and sweets, which is important for keeping triglycerides in check.",
      "linked_biomarker": "triglycerides"
    },
    {
      "item": "Sunlight: sit or walk in direct sun for 10-15 minutes between 11 am and 1 pm, 4 times a week, with arms and face exposed (no sunscreen for those minutes). Stop before the skin turns pink; skip the middle of the day if it is very hot and use early morning sun instead.",
      "rationale": "Regular short sun exposure is the main natural way to raise vitamin D, which is low at 15.22 ng/mL; your doctor will decide if any supplement is needed.",
      "linked_biomarker": "vitamin_d"
    },
    {
      "item": "Vitamin D foods daily: 1 bowl (150 g) curd or 1 glass (200 ml) toned milk at breakfast, 30 g paneer 2-3 times a week, and UV-exposed mushrooms (button mushrooms kept in sunlight for 30 minutes, then cooked) twice a week. Ask your FOXO doctor before starting any supplement.",
      "rationale": "Dairy and UV-exposed mushrooms are among the few vegetarian foods that carry meaningful vitamin D and support correction of the low level alongside sun exposure.",
      "linked_biomarker": "vitamin_d"
    },
    {
      "item": "Cooking and seasoning: use 3-4 tsp of oil in total for the whole day (mustard, rice bran, groundnut-free, or a little olive oil for salads). Use ghee sparingly, no more than 1 tsp a day. Flavour food with jeera, ajwain, haldi, hing, lemon and fresh coriander instead of deep-frying.",
      "rationale": "Cutting total visible fat and fried food lowers both LDL and triglycerides; this amount of oil keeps food practical and Jain-compatible without onion or garlic.",
      "linked_biomarker": "ldl"
    }
  ],
  "foods_to_avoid": [
    "Peanuts in every form: peanut butter, peanut chutney, groundnut oil, chikki, and any namkeen or sweet with peanuts or 'may contain peanut' labels",
    "Onion, garlic, potato, carrot, beetroot, radish, ginger and other root vegetables (Jain diet) - use hing, jeera, ajwain and lemon for flavour",
    "Honey, eggs, meat, fish and seafood (Jain diet)",
    "Sugar, jaggery, sweets, mithai, halwa, pastries, cakes, biscuits, rusk, ice cream and sweetened drinks or packaged fruit juices - these raise triglycerides sharply",
    "Deep-fried snacks such as samosa, kachori, puri, bhajiya, papad fried in oil and readymade namkeen",
    "Bakery and maida items (bread, khari, puff pastry, naan) made with vanaspati or palm oil",
    "Excess coconut oil, palm oil, butter and cream; keep ghee to about 1 tsp a day",
    "Skip reheated fried leftovers and very large rice portions at night"
  ],
  "activity": "Your doctor has not restricted exercise, but because your triglycerides and LDL need a cardiology review, stay with gentle activity only. Start with a 15-20 minute easy walk at a comfortable pace, building to 30 minutes, 5 days a week, preferably in the morning or early evening. Add 10 minutes of gentle yoga or stretching at home (simple forward bend, tadasana, seated twist) and light household activity. Avoid heavy weight training, high-intensity workouts and long fasted workouts until your cardiology review. Stop at once and contact your doctor if you feel chest pain, breathlessness, palpitations or dizziness, and follow all of your doctor's advice.",
  "sleep": "Aim for 7-8 hours of sleep, going to bed and waking at the same time every day, including weekends. Finish dinner by 8-8:30 pm so there are 2-3 hours before lying down. Switch off mobile and TV screens 30 minutes before bed, keep the room dark and cool, and avoid tea or coffee after 5 pm. Poor sleep worsens triglycerides and insulin resistance, so treat it as part of your lipid management.",
  "retest_in_weeks": 12
}
